let updateStatus={phase:window.neonDesktop?'idle':'browser',currentVersion:STUDIO_VERSION};
function drawUpdateStatus(next=updateStatus){updateStatus=next;const section=document.querySelector('#studio-updates');if(section)section.innerHTML=updatePanel(updateStatus,!!window.neonDesktop);const notice=document.querySelector('#studio-update-notice');if(notice){notice.innerHTML=updateNotice(updateStatus);notice.hidden=!notice.innerHTML;}}
const $ = (s,root=document)=>root.querySelector(s);
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',library:'<path d="M9 18V5l12-2v13M9 9l12-2"/><ellipse cx="6" cy="18" rx="3" ry="3"/><ellipse cx="18" cy="16" rx="3" ry="3"/>',albums:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="2"/><path d="M5 12a7 7 0 0 1 7-7M19 12a7 7 0 0 1-7 7"/>',playlists:'<path d="M3 5h13M3 10h13M3 15h8M16 14v7l6-3.5Z"/>',events:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18M7 15h3M14 15h3"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m10 2-1 3-3 1-3-1-2 4 2 3-1 3 3 3 3-1 3 1 2 3 4-2v-3l2-2 3-1v-4l-3-1-2-3V3l-4-1-2 2Z"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.library}</svg>`;
