let state=newState(), currentView='overview', search='', currentId=null, queue=[], shuffle=false, repeat=false, importing=false, publishing=false, connected=false, installPrompt, preserveSearch=false;
let saveChain=Promise.resolve();
let teamStatus={text:'Verbindung zu Supabase wird hergestellt …',type:'local'},discordStatus='Discord noch nicht verbunden.',remoteTrack=null;
const team=new TeamClient({getState:()=>state,setState:next=>{state=next;saveState(structuredClone(state)).catch(fail);render();renderNowPlaying();},getBlob,putBlob,onStatus:(text,type)=>{teamStatus={text,type};const el=$('#team-status');if(el)el.textContent=text;$('#connection-status').textContent=team.user?`${team.user.alias} · Team verbunden`:'Lokal gespeichert';},onConflict:()=>{teamStatus={text:'Ein gemeinsamer Eintrag wurde gleichzeitig geändert. Bitte den Konflikt prüfen.',type:'conflict'};showTeamConflict();}});
