const toast=(message,error=false)=>{const box=$('#toast');box.textContent=message;box.hidden=false;box.classList.toggle('danger-text',error);clearTimeout(toast.timer);toast.timer=setTimeout(()=>box.hidden=true,error?9000:4800);};
const fail=e=>{console.error(e?.message||e);toast(e?.message||'Das hat nicht geklappt. Bitte erneut versuchen.',true);};
function persist(renderAgain=true){const copy=structuredClone(state);saveChain=saveChain.catch(()=>{}).then(async()=>{await saveState(copy);if(team.active)await team.push(copy);});return saveChain.then(()=>{if(renderAgain)render();});}
async function objectURL(key){if(!key)return '';if(urlCache.has(key))return urlCache.get(key);const blob=await team.fetchBlob(key);if(!blob)return '';const url=URL.createObjectURL(blob);urlCache.set(key,url);return url;}
function releaseURL(key){if(urlCache.has(key)){URL.revokeObjectURL(urlCache.get(key));urlCache.delete(key);}}
function hydrateImages(root=document){for(const img of root.querySelectorAll('[data-blob]'))objectURL(img.dataset.blob).then(url=>{if(url&&img.isConnected)img.src=url;}).catch(fail);}
function cover(album,cls='cover'){return `<div class="${cls}">${album?.coverBlobId?`<img data-blob="${h(album.coverBlobId)}" src="assets/logo.svg" alt="Cover: ${h(album.title)}">`:'<img class="cover-mark" src="assets/logo.svg" alt=""><span class="cover-caption">NEON TRINITY</span>'}</div>`;}
function empty(title,description,action,button,symbol='♫',small=false){return `<div class="empty ${small?'small':''}"><span class="empty-symbol">${symbol}</span><h3>${title}</h3><p>${description}</p>${action?`<button class="button ${small?'ghost':'primary'}" data-action="${action}">${button}</button>`:''}</div>`;}
function heading(title,description,action,button){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${action?`<button class="button primary" data-action="${action}">＋ ${button}</button>`:''}</div>`;}
function uploadZone(){return '<div class="upload-zone" data-action="import" role="button" tabindex="0"><span class="upload-icon">↥</span><div><strong>Dein Sound gehört hierher.</strong><p>MP3s hier ablegen oder Dateien auf deinem Computer auswählen · bis 48 MiB pro Song</p></div><span class="button ghost compact">Dateien auswählen</span></div>';}
function playlistsForView(){return visiblePlaylists(state,team.user?.id);}
function playlistLabel(p){return p.visibility==='private'?'Nur für mich':'Für die Band';}
function filteredTracks(){return state.tracks.filter(t=>`${t.title} ${t.artist} ${t.voices} ${t.genre||''}`.toLowerCase().includes(search.toLowerCase()));}
function trackTable(tracks,context='library') {
  if(!tracks.length)return empty(search?'Keine Treffer':'Noch ist es hier still.',search?'Versuch einen anderen Suchbegriff.':'Importiere deine ersten MP3s und mach das Studio zu eurem Soundarchiv.',search?null:'import','MP3s importieren');
  return `<div class="table-wrap"><table class="track-table"><thead><tr><th>#</th><th>Titel</th><th>Stimmen</th><th>Dauer</th><th></th></tr></thead><tbody>${tracks.map((t,i)=>`<tr class="${t.id===currentId?'selected-track':''}"><td class="number">${String(i+1).padStart(2,'0')}</td><td><div class="song-cell"><button class="song-art" data-action="play-track" data-id="${h(t.id)}" data-context="${h(context)}" title="Abspielen" aria-label="${h(t.title)} abspielen">${t.coverBlobId?`<img data-blob="${h(t.coverBlobId)}" src="assets/logo.svg" alt="">`:'▶'}</button><div><strong>${h(t.title)}</strong><small>${h(t.artist)}</small></div></div></td><td><span class="tag">${h(t.voices||'DEX · NIX · JAX')}</span></td><td class="duration">${time(t.duration)}</td><td><div class="row-actions"><button class="icon-button" data-action="add-to-playlist" data-id="${h(t.id)}" title="Zu Playlist hinzufügen" aria-label="Zu Playlist hinzufügen">＋</button><button class="icon-button" data-action="edit-track" data-id="${h(t.id)}" title="Song bearbeiten" aria-label="Song bearbeiten">⋯</button></div></td></tr>`).join('')}</tbody></table></div>`;
}
function albumCard(a){return `<article class="album-card"><a href="#album/${h(a.id)}">${cover(a)}<h3>${h(a.title)}</h3></a><p>${h(a.year)} · ${a.trackIds.length} Songs · ${time(duration(a.trackIds,state.tracks))}</p><div class="card-actions"><span class="badge ${state.published[a.id]?'live':''}">${state.published[a.id]?'VERÖFFENTLICHT':'ENTWURF'}</span><button class="text-link" data-action="edit-album" data-id="${h(a.id)}">Bearbeiten ↗</button></div></article>`;}
function eventCard(event,compact=false){const date=new Date(event.date),valid=!isNaN(date),playlist=state.playlists.find(p=>p.id===event.playlistId);return `<article class="event-card"><div class="date-box"><strong>${valid?date.getDate():'–'}</strong><small>${valid?date.toLocaleDateString('de-DE',{month:'short'}):'OFFEN'}</small></div><div class="event-info"><h3>${h(event.title)}</h3><p>${valid?date.toLocaleDateString('de-DE',{weekday:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'Termin noch offen'}<br>${h(event.location||'Ort folgt')} · ${playlist?`${playlist.trackIds.length} Songs / ${time(duration(playlist.trackIds,state.tracks))}`:'Setlist noch offen'}</p></div><div class="event-controls">${playlist?`<button class="icon-button" data-action="play-playlist" data-id="${h(playlist.id)}" title="Setlist abspielen" aria-label="Setlist abspielen">▶</button>`:''}<button class="icon-button" data-action="edit-event" data-id="${h(event.id)}" title="Auftritt bearbeiten" aria-label="Auftritt bearbeiten">⋯</button></div></article>`;}
function overview(){const next=[...state.events].filter(e=>new Date(e.date).getTime()>=Date.now()-86400000).sort((a,b)=>a.date.localeCompare(b.date))[0];return `${heading('Willkommen im Studio.','Alles für euren Sound. Alles für eure nächste Show.')}<section class="hero"><div class="live-tag"><i class="status-dot"></i> DEX · NIX · JAX</div><div class="hero-copy"><div class="eyebrow">THIS IS YOUR FREQUENCY.</div><h2>Drei Stimmen.<br><span>Ein Puls.</span></h2><p>Von der ersten Idee bis zur letzten Zugabe.<br>Euer Sound hat jetzt ein Zuhause.</p><div class="hero-actions"><button class="button primary" data-action="import">↥ Musik importieren</button><a class="button ghost" href="#events">Nächste Show planen ↗</a></div></div><div class="hero-art" aria-hidden="true"><img src="assets/neon-trinity.png" alt=""><span class="orbit-label">NEON TRINITY</span></div></section><div class="stats-grid">${[['library',state.tracks.length,'Songs in der Mediathek'],['albums',state.albums.length,'Eigene Alben'],['playlists',playlistsForView().length,'Playlists & Setlists'],['events',state.events.length,'Geplante Auftritte']].map(([key,value,label])=>`<a class="stat" href="#${key}"><div class="stat-icon">${icon(key)}</div><div><strong>${value.toString().padStart(2,'0')}</strong><small>${label}</small></div></a>`).join('')}</div><div class="overview-columns"><section><div class="section-header"><h2>Eure Alben</h2><a class="text-link" href="#albums">Alle ansehen ↗</a></div>${state.albums.length?`<div class="cards">${state.albums.slice(-2).reverse().map(albumCard).join('')}</div>`:empty('Der nächste Release beginnt hier.','Pack eure Songs in ein Album, gib ihm ein Cover und teile es mit der Welt.','new-album','Erstes Album erstellen','◉',true)}</section><section><div class="section-header"><h2>Auf die Bühne.</h2><a class="text-link" href="#events">Auftritte ↗</a></div>${next?eventCard(next,true):empty('Die nächste Show wartet.','Plane euren Auftritt und stell die passende Setlist aus der Mediathek zusammen.','new-event','Auftritt planen','⚡',true)}</section></div><section><div class="section-header" id="recent-header"><h2>Zuletzt hinzugefügt</h2><a class="text-link" href="#library">Zur Mediathek ↗</a></div>${state.tracks.length?trackTable([...state.tracks].reverse().slice(0,5),'recent'):uploadZone()}</section>`;}
function library(){return `${heading('Euer Soundarchiv.','Alle Songs an einem Ort. Bereit für Alben, Playlists und die Bühne.','import','MP3s importieren')}${uploadZone()}<div class="toolbar"><span class="eyebrow">MEDIATHEK</span><span class="badge">${filteredTracks().length} SONGS · ${time(duration(filteredTracks().map(t=>t.id),state.tracks))}</span></div>${trackTable(filteredTracks())}`;}
function albumsView(){const list=state.albums.filter(a=>`${a.title} ${a.description}`.toLowerCase().includes(search.toLowerCase()));return `${heading('Musik, die bleibt.','Deine Alben. Dein Cover. Ein eigener Link für jeden Release.','new-album','Album erstellen')}${list.length?`<div class="cards">${list.map(albumCard).join('')}<button class="card-add" data-action="new-album"><span>＋</span>Neues Album</button></div>`:empty('Mach aus Songs einen Release.','Wähle Titel aus deiner Mediathek, lade ein Cover hoch und gestalte eure eigene Albumseite.','new-album','Album erstellen','◉')}`;}
function albumDetail(key){const a=state.albums.find(x=>x.id===key);if(!a)return empty('Album nicht gefunden.','Gehe zurück zur Albumübersicht.');const tracks=a.trackIds.map(k=>state.tracks.find(t=>t.id===k)).filter(Boolean);return `<div class="toolbar"><a class="text-link" href="#albums">← Zurück zu den Alben</a></div><section class="album-detail-hero">${cover(a)}<div><div class="eyebrow">NEON TRINITY · ALBUM</div><h1>${h(a.title)}</h1><p>${h(a.year)} · ${tracks.length} Songs · ${time(duration(a.trackIds,state.tracks))}<br>${h(a.description||'')}</p><div class="hero-actions"><button class="button primary" data-action="play-album" data-id="${h(a.id)}" ${tracks.length?'':'disabled'}>▶ Abspielen</button><button class="button ghost" data-action="edit-album" data-id="${h(a.id)}">Bearbeiten</button><button class="button ghost" data-action="publish-album" data-id="${h(a.id)}">↗ ${state.published[a.id]?'Aktualisieren & teilen':'Album veröffentlichen'}</button></div></div></section>${state.published[a.id]?`<div class="note"><strong>Albumseite vorbereitet / veröffentlicht</strong><br><a class="public-link" href="${h(albumLink(a.id,state.settings))}" target="_blank" rel="noopener">${h(albumLink(a.id,state.settings))}</a> <button class="text-link" data-action="copy-link" data-id="${h(a.id)}">Link kopieren</button><br>Freigegebene Alben werden direkt aus Supabase geladen. Eure Player-Website muss einmal bereitgestellt sein.</div>`:''}${trackTable(tracks,`album/${a.id}`)}`;}
function playlistsView(){const list=playlistsForView().filter(p=>`${p.title} ${p.description}`.toLowerCase().includes(search.toLowerCase()));return `${heading('Die richtige Reihenfolge.','Playlists für jeden Moment. Setlists für jede Show.','new-playlist','Playlist erstellen')}${list.length?`<div class="grid-two">${list.map(p=>`<article class="playlist-card"><div class="playlist-icon">☷</div><div><h3>${h(p.title)}</h3><span class="badge">${playlistLabel(p)}</span><p>${p.trackIds.length} Songs · ${time(duration(p.trackIds,state.tracks))}</p><button class="text-link" data-action="play-playlist" data-id="${h(p.id)}">▶ Abspielen</button> <button class="text-link" data-action="edit-playlist" data-id="${h(p.id)}">Bearbeiten ↗</button></div></article>`).join('')}</div>`:empty('Gib eurer Show einen Flow.','Stell Songs aus der Mediathek zusammen, ändere ihre Reihenfolge und verknüpfe die Playlist mit einem Auftritt.','new-playlist','Erste Playlist erstellen','☷')}`;}
function eventsView(){const list=[...state.events].filter(e=>`${e.title} ${e.location}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>a.date.localeCompare(b.date));return `${heading('Bis zur letzten Zugabe.','Auftritte planen, Setlists zuordnen und bereit für die Bühne sein.','new-event','Auftritt planen')}${list.length?`<div class="event-list">${list.map(e=>eventCard(e)).join('')}</div>`:empty('Wann ist eure nächste Show?','Trag Datum, Uhrzeit und Ort ein. Die passende Setlist wählst du aus euren Playlists.','new-event','Ersten Auftritt planen','⚡')}`;}
function settingsView(){return studioSettings({state,connected,desktop:!!window.neonDesktop,backgroundSettings,updateStatus});}
function render(){
  currentView=(location.hash.slice(1).split('/')[0]||'overview');if(!labels[currentView]&&!['album','listen'].includes(currentView))currentView='overview';
  const navView=currentView==='album'?'albums':currentView==='listen'?'team':currentView;
  $('#navigation').innerHTML=Object.entries(labels).filter(([k])=>k!=='settings').map(([key,label])=>`<a href="#${key}" class="nav-item ${key===navView?'active':''}" ${key===navView?'aria-current="page"':''}>${icon(key)}${label}</a>`).join('');
  $('#sidebar-playlists').innerHTML=playlistsForView().length?playlistsForView().slice(0,7).map(p=>`<button data-action="edit-playlist" data-id="${h(p.id)}">☷ &nbsp;${h(p.title)}${p.visibility==='private'?' · Privat':''}</button>`).join(''):'<p>Noch keine Setlist.<br>Die nächste Show wartet schon.</p>';
  $('#breadcrumb').textContent=labels[navView];document.documentElement.dataset.theme=state.theme;$('#theme-name').textContent=THEMES[state.theme];
  $('#main').innerHTML=currentView==='overview'?overview():currentView==='library'?library():currentView==='albums'?albumsView():currentView==='album'?albumDetail(location.hash.split('/')[1]):currentView==='playlists'?playlistsView():currentView==='events'?eventsView():currentView==='team'?teamView({team,status:teamStatus,state,listening,discordStatus,desktop:!!window.neonDesktop}):currentView==='listen'?listeningView(listening.followRoom,listening):settingsView();
  $('#connection-status').textContent=team.active?`${team.user.alias} · Team verbunden`:connected?'GitHub verbunden':'Lokal gespeichert';
  drawUpdateStatus();hydrateImages();applyBackground();if(currentView==='settings'){$('#github-form')?.addEventListener('submit',saveGithub);bindBackgroundSettings();}if(currentView==='team')bindTeamForms();
  document.title=`${labels[navView]} · Neon Trinity Studio`;
}
function showModal(content){$('#modal-content').innerHTML=content;const dialog=$('#modal');if(!dialog.open)dialog.showModal();hydrateImages(dialog);dialog.scrollTop=0;}
function closeModal(){$('#modal').close();}
async function confirmAction(title,description,button,onConfirm){showModal(`<h2>${h(title)}</h2><p class="subtitle">${h(description)}</p><div class="form-actions"><button class="button ghost" id="cancel-confirm">Abbrechen</button><button class="button danger" id="confirm-action">${h(button)}</button></div>`);$('#cancel-confirm').onclick=closeModal;$('#confirm-action').onclick=async e=>{e.currentTarget.disabled=true;try{await onConfirm();closeModal();}catch(err){fail(err);if($('#confirm-action'))$('#confirm-action').disabled=false;}};}
async function getDuration(file){return new Promise((resolve,reject)=>{const a=new Audio();const url=URL.createObjectURL(file);let timer;const finish=(error)=>{clearTimeout(timer);const d=a.duration;a.removeAttribute('src');a.load();URL.revokeObjectURL(url);error?reject(error):resolve(d);};a.onloadedmetadata=()=>{if(!Number.isFinite(a.duration)||a.duration<=0)finish(new Error('Die Audiodauer konnte nicht gelesen werden.'));else finish();};a.onerror=()=>finish(new Error('Die Datei ist keine lesbare MP3.'));timer=setTimeout(()=>finish(new Error('Das Lesen der MP3 hat zu lange gedauert.')),20000);a.src=url;});}
async function importFiles(files){if(importing)return toast('Ein Import läuft bereits.');importing=true;const errors=[];let count=0,duplicates=0;try{for(const file of files){try{validateAudio(file);toast(`${file.name} wird importiert …`);const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer())),n=>n.toString(16).padStart(2,'0')).join('');if(state.tracks.some(t=>t.digest===digest)){duplicates++;continue;}const seconds=await getDuration(file),blobId=id(),track={id:id(),blobId,title:file.name.replace(/\.mp3$/i,'').replace(/_/g,' '),artist:'Neon Trinity',voices:'Dex · Nix · Jax',genre:'',duration:seconds,size:file.size,digest,addedAt:new Date().toISOString()};await putBlob(blobId,new Blob([file],{type:'audio/mpeg'}));state.tracks.push(track);count++;await persist(false);}catch(e){errors.push(e.message);}}render();toast(`${count} Song${count===1?'':'s'} importiert.${duplicates?` ${duplicates} Duplikat${duplicates===1?'':'e'} übersprungen.`:''}${errors.length?` ${errors.length} Datei(en) konnten nicht importiert werden.`:''}`,!!errors.length);if(errors.length)showModal(`<h2>Import abgeschlossen.</h2><p class="subtitle">${count} Song(s) wurden gespeichert.</p><div class="note">${errors.map(h).join('<br>')}</div>`);if(count&&navigator.storage?.persist)navigator.storage.persist().catch(()=>{});}finally{importing=false;$('#audio-files').value='';}}
function trackForm(key){const t=state.tracks.find(t=>t.id===key);if(!t)return;showModal(`<h2>Song bearbeiten.</h2><p class="subtitle">${h(t.title)} · ${time(t.duration)} · ${(t.size/1024/1024).toFixed(1)} MiB</p><form id="track-form" class="form-grid"><label class="field"><span>Titel</span><input name="title" value="${h(t.title)}" maxlength="160" required></label><div class="form-row"><label class="field"><span>Interpret</span><input name="artist" value="${h(t.artist)}" maxlength="120" required></label><label class="field"><span>Stimmen</span><input name="voices" value="${h(t.voices)}" maxlength="120"></label></div><label class="field"><span>Genre / Notiz</span><input name="genre" value="${h(t.genre||'')}" maxlength="120"></label><label class="field"><span>Eigenes Songcover (optional)</span><input name="cover" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="form-actions"><button class="button danger" type="button" id="delete-track">Song löschen</button><button class="button primary">Speichern</button></div></form>`);$('#track-form').onsubmit=async e=>{e.preventDefault();try{const form=new FormData(e.target),file=form.get('cover');let coverBlobId=t.coverBlobId;if(file?.size){validateImage(file);coverBlobId=id();await putBlob(coverBlobId,new Blob([file],{type:file.type}));}Object.assign(t,{title:form.get('title').trim()||t.title,artist:form.get('artist').trim()||'Neon Trinity',voices:form.get('voices').trim(),genre:form.get('genre').trim(),coverBlobId});await persist();closeModal();toast('Song gespeichert.');}catch(err){fail(err);}};$('#delete-track').onclick=()=>confirmAction('Song löschen?',`„${t.title}“ wird aus deiner Mediathek und bei aktiver Teamverbindung auch aus der gemeinsamen Mediathek entfernt. Veröffentlichte Albumseiten werden beim nächsten Abgleich aktualisiert.`,'Song löschen',async()=>{if(currentId===t.id){audio.pause();audio.removeAttribute('src');currentId=null;renderNowPlaying();}removeTrack(state,t.id);queue=queue.filter(k=>k!==t.id);await persist();await deleteBlob(t.blobId);releaseURL(t.blobId);toast('Song gelöscht.');});}
function groupForm(kind,key=null,initialTrack=null,onSaved=null){
  const isAlbum=kind==='album',collection=isAlbum?state.albums:playlistsForView(),existing=collection.find(a=>a.id===key),data=existing||{id:id(),title:'',description:'',year:new Date().getFullYear(),trackIds:initialTrack?[initialTrack]:[]};let selected=[...data.trackIds];
  showModal(`<h2>${isAlbum?'Dein nächster Release.':'Deine nächste Setlist.'}</h2><p class="subtitle">${isAlbum?'Ein Album, ein Cover, eure Geschichte.':'Wähle Songs aus der Mediathek und bring sie in die richtige Reihenfolge.'}</p><form id="group-form" class="form-grid"><div class="${isAlbum?'form-row':''}"><label class="field"><span>${isAlbum?'Albumtitel':'Name der Playlist'}</span><input name="title" value="${h(data.title)}" placeholder="${isAlbum?'Wie heißt euer Album?':'z. B. Live in Estelglin'}" maxlength="160" required></label>${isAlbum?`<label class="field"><span>Erscheinungsjahr</span><input name="year" type="number" value="${h(data.year)}" min="1900" max="2200" required></label>`:''}</div>${!isAlbum?`<label class="field"><span>Sichtbarkeit</span><select name="visibility" ${existing?'disabled':''}><option value="band" ${data.visibility!=='private'?'selected':''}>Für die Band · Dex, Nix & Jax</option><option value="private" ${data.visibility==='private'?'selected':''} ${!team.active||onSaved?'disabled':''}>Nur für mich</option></select></label><p class="notice">${existing?'Die Sichtbarkeit wurde beim Erstellen festgelegt. Für eine andere Sichtbarkeit kannst du eine neue Playlist erstellen.':onSaved?'Setlists für gemeinsame Auftritte sind für die Band sichtbar.':'Nur für mich: Die Playlist gehört deinem Discord-Konto. Für die Band: Alle drei können sie sehen und bearbeiten.'}${!team.active?' Für persönliche Playlists bitte zuerst mit Discord anmelden.':''}</p>`:''}<label class="field"><span>Beschreibung (optional)</span><textarea name="description" maxlength="1800">${h(data.description)}</textarea></label>${isAlbum?`<label class="field"><span>Albumcover · JPG, PNG oder WebP</span><input type="file" id="album-cover" name="cover" accept="image/png,image/jpeg,image/webp"></label><img class="cover-preview" id="cover-preview" ${data.coverBlobId?`data-blob="${h(data.coverBlobId)}" src="assets/logo.svg"`:'hidden src="assets/logo.svg"'} alt="Covervorschau">`:''}<div><div class="form-section">Songs aus der Mediathek</div><input class="selection-search" id="picker-search" placeholder="Song suchen …" aria-label="Songs auswählen und suchen"><div class="selection-list" id="song-selection"></div><div class="form-section">Reihenfolge <span id="selection-info"></span></div><div class="ordered-tracks" id="ordered-tracks"></div></div><div class="form-actions">${existing?`<button type="button" class="button danger" id="delete-group">${isAlbum?'Album':'Playlist'} löschen</button>`:''}<button class="button primary">${isAlbum?'Album':'Playlist'} speichern</button></div></form>`);
  const renderPicker=()=>{const term=$('#picker-search').value.toLowerCase(),tracks=state.tracks.filter(t=>`${t.title} ${t.artist}`.toLowerCase().includes(term));$('#song-selection').innerHTML=tracks.length?tracks.map(t=>`<label class="track-choice"><input type="checkbox" value="${h(t.id)}" ${selected.includes(t.id)?'checked':''}><span>${h(t.title)}</span><small>${time(t.duration)}</small></label>`).join(''):'<p class="notice">Keine passenden Songs. Importiere zuerst MP3s in der Mediathek.</p>';$('#ordered-tracks').innerHTML=selected.map((k,i)=>{const t=state.tracks.find(t=>t.id===k);return t?`<div class="track-choice"><span class="order-number">${i+1}</span><span>${h(t.title)}</span><button type="button" class="icon-button" data-order="${i}" data-direction="-1" aria-label="Song nach oben" ${i?'':'disabled'}>↑</button><button type="button" class="icon-button" data-order="${i}" data-direction="1" aria-label="Song nach unten" ${i===selected.length-1?'disabled':''}>↓</button><button type="button" class="icon-button" data-remove="${h(k)}" aria-label="Song aus Auswahl entfernen">×</button></div>`:'';}).join('');$('#selection-info').textContent=`· ${selected.length} Songs · ${time(duration(selected,state.tracks))}`;};
  $('#picker-search').oninput=renderPicker;$('#song-selection').onchange=e=>{const k=e.target.value;if(e.target.checked){if(!selected.includes(k))selected.push(k);}else selected=selected.filter(x=>x!==k);renderPicker();};$('#ordered-tracks').onclick=e=>{const btn=e.target.closest('button');if(!btn)return;if(btn.dataset.remove)selected=selected.filter(k=>k!==btn.dataset.remove);else selected=move(selected,Number(btn.dataset.order),Number(btn.dataset.direction));renderPicker();};renderPicker();
  let previewURL;
  if(isAlbum)$('#album-cover').onchange=e=>{const f=e.target.files[0];if(!f)return;try{validateImage(f);if(previewURL)URL.revokeObjectURL(previewURL);previewURL=URL.createObjectURL(f);$('#cover-preview').src=previewURL;$('#cover-preview').hidden=false;}catch(err){e.target.value='';fail(err);}};
  $('#group-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type="submit"],.form-actions .primary');button.disabled=true;try{const form=new FormData(e.target),file=form.get('cover');let coverBlobId=data.coverBlobId;if(file?.size){validateImage(file);coverBlobId=id();await putBlob(coverBlobId,new Blob([file],{type:file.type}));}const title=form.get('title').trim();if(!title)throw new Error('Bitte einen Namen eingeben.');const record={...data,title,description:form.get('description').trim(),trackIds:selected,...(isAlbum?{year:Number(form.get('year')),coverBlobId}:{})};if(!isAlbum&&(existing?.visibility==='private'||(!existing&&form.get('visibility')==='private'))){await team.savePrivate(record);}else{if(existing)Object.assign(existing,record);else(isAlbum?state.albums:state.playlists).push(record);}await persist();if(previewURL)URL.revokeObjectURL(previewURL);closeModal();toast(`${isAlbum?'Album':'Playlist'} gespeichert.`);if(onSaved)onSaved(record);}catch(err){fail(err);button.disabled=false;}};
  if(existing)$('#delete-group').onclick=()=>confirmAction(`${isAlbum?'Album':'Playlist'} löschen?`,isAlbum?'Die Songs bleiben in der Mediathek. Eine bestehende öffentliche Albumfreigabe wird bei aktiver Teamverbindung ebenfalls zurückgezogen.':'Die Songs bleiben in der Mediathek. Die Zuordnung dieser Setlist zu Auftritten wird entfernt.','Löschen',async()=>{if(isAlbum){if(team.active&&state.published[key]){const result=await team.backend.publish(Object.keys(state.published).filter(id=>id!==key),state.theme);team.accept(result.catalog);}state.albums=state.albums.filter(a=>a.id!==key);delete state.published[key];}else if(existing.visibility==='private'){await team.deletePrivate(existing);}else{state.playlists=state.playlists.filter(p=>p.id!==key);for(const ev of state.events)if(ev.playlistId===key)ev.playlistId='';}await persist();if(isAlbum&&currentView==='album')location.hash='albums';toast('Lokal gelöscht.');});
}
function eventForm(key){const existing=state.events.find(e=>e.id===key),ev=existing||{id:id(),title:'',date:'',location:'',playlistId:'',notes:''};showModal(`<h2>Die nächste Show.</h2><p class="subtitle">Datum setzen. Setlist wählen. Bühne übernehmen.</p><form id="event-form" class="form-grid"><label class="field"><span>Name des Auftritts</span><input name="title" value="${h(ev.title)}" maxlength="160" required placeholder="z. B. Neon Nights · Estelglin"></label><div class="form-row"><label class="field"><span>Datum & Uhrzeit · lokale Zeit</span><input name="date" type="datetime-local" value="${h(ev.date)}" required></label><label class="field"><span>Ort / Server</span><input name="location" value="${h(ev.location)}" maxlength="180" placeholder="Bühne, Club oder RP-Ort"></label></div><label class="field"><span>Eigene Playlist / Setlist</span><select name="playlistId"><option value="">Noch keine Setlist zuordnen</option>${state.playlists.map(p=>`<option value="${h(p.id)}" ${p.id===ev.playlistId?'selected':''}>${h(p.title)} · ${p.trackIds.length} Songs</option>`).join('')}</select></label><button type="button" id="event-new-playlist" class="text-link">＋ Neue Setlist für diesen Auftritt erstellen</button><label class="field"><span>Notizen</span><textarea name="notes" maxlength="2000">${h(ev.notes)}</textarea></label><div class="form-actions">${existing?'<button type="button" class="button danger" id="delete-event">Auftritt löschen</button>':''}<button class="button primary">Auftritt speichern</button></div></form>`);$('#event-form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target),record={...ev,...Object.fromEntries(f.entries())};record.title=record.title.trim();if(!record.title||isNaN(new Date(record.date)))throw new Error('Bitte einen Namen und einen gültigen Termin eingeben.');if(existing)Object.assign(existing,record);else state.events.push(record);await persist();closeModal();toast('Auftritt gespeichert.');}catch(err){fail(err);}};$('#event-new-playlist').onclick=()=>{const f=Object.fromEntries(new FormData($('#event-form')).entries());Object.assign(ev,f);if(!existing){state.events.push(ev);}groupForm('playlist',null,null,async p=>{ev.playlistId=p.id;await persist();eventForm(ev.id);});};if(existing)$('#delete-event').onclick=()=>confirmAction('Auftritt löschen?','Die zugehörige Playlist bleibt erhalten.','Löschen',async()=>{state.events=state.events.filter(e=>e.id!==ev.id);await persist();toast('Auftritt gelöscht.');});}
function addToPlaylist(key){if(!playlistsForView().length)return groupForm('playlist',null,key);showModal(`<h2>Zur Playlist hinzufügen.</h2><p class="subtitle">Wähle die passende Setlist.</p><div class="selection-list">${playlistsForView().map(p=>`<button class="track-choice" data-add-playlist="${h(p.id)}"><span>${h(p.title)}</span><small>${playlistLabel(p)} · ${p.trackIds.length} Songs</small></button>`).join('')}</div><div class="form-actions"><button id="new-from-song" class="button primary">＋ Neue Playlist</button></div>`);$('#new-from-song').onclick=()=>groupForm('playlist',null,key);for(const btn of document.querySelectorAll('[data-add-playlist]'))btn.onclick=async()=>{const p=playlistsForView().find(x=>x.id===btn.dataset.addPlaylist);if(!p.trackIds.includes(key)){if(p.visibility==='private')await team.savePrivate({...p,trackIds:[...p.trackIds,key]});else p.trackIds.push(key);}await persist();closeModal();toast('Song zur Playlist hinzugefügt.');};}
function contextQueue(context){if(context==='queue')return [...queue];if(context==='recent')return [...state.tracks].reverse().slice(0,5).map(t=>t.id);if(context?.startsWith('album/'))return state.albums.find(a=>a.id===context.split('/')[1])?.trackIds||[];return filteredTracks().map(t=>t.id);}
async function playTrack(key,ids){const track=state.tracks.find(t=>t.id===key);if(!track)return;if(listening.followRoom)await listening.leave();remoteTrack=null;if(ids)queue=[...ids];if(!queue.includes(key))queue=[key];const src=await objectURL(track.blobId);if(!src)throw new Error('Diese MP3 fehlt im lokalen Speicher. Bitte erneut importieren oder ein Backup wiederherstellen.');currentId=key;audio.src=src;renderNowPlaying();await audio.play();render();if('mediaSession'in navigator){navigator.mediaSession.metadata=new MediaMetadata({title:track.title,artist:track.artist,album:'Neon Trinity'});}}
function renderNowPlaying(){const track=state.tracks.find(t=>t.id===currentId)||remoteTrack;$('#now-playing').innerHTML=track?`<div class="mini-art">${track.coverBlobId?`<img data-blob="${h(track.coverBlobId)}" src="assets/logo.svg" alt="">`:'♫'}</div><div><strong>${h(track.title)}</strong><small>${h(track.artist)} · ${h(track.voices||'')}</small></div>`:'<div class="mini-art">♫</div><div><strong>Dein nächster Lieblingssong</strong><small>Wähle einen Song aus deiner Mediathek</small></div>';hydrateImages($('#now-playing'));$('#total-time').textContent=time(track?.duration||0);}
function nextTrack(direction=1,auto=false){if(!queue.length)return;let index=queue.indexOf(currentId)+direction;if(shuffle&&queue.length>1){const options=queue.filter(k=>k!==currentId);return playTrack(options[Math.floor(Math.random()*options.length)]).catch(fail);}if(index>=queue.length){if(auto&&!repeat)return;index=0;}if(index<0)index=queue.length-1;playTrack(queue[index]).catch(fail);}
async function saveGithub(e){e.preventDefault();const form=new FormData(e.target),btn=e.target.querySelector('button[type=submit]');btn.disabled=true;try{const settings={owner:form.get('owner').trim(),repo:form.get('repo').trim(),baseUrl:safeBaseUrl(form.get('baseUrl'))};if(form.get('token').trim()){const profile=await connect(form.get('token'));connected=true;toast(`Verbunden als ${profile.login}.`);}state.settings={...state.settings,...settings};await persist();toast('GitHub-Einstellungen gespeichert.');}catch(err){fail(err);btn.disabled=false;}}
function tokenHelp(){showModal('<h2>GitHub verbinden.</h2><p class="subtitle">Du gibst den Token ausschließlich in deinem Studio ein.</p><div class="help-steps"><div class="help-step"><div>Öffne <a class="public-link" href="https://github.com/settings/personal-access-tokens/new" target="_blank" rel="noopener">GitHub → Fine-grained personal access tokens</a>. Vergib einen Namen und ein Ablaufdatum.</div></div><div class="help-step"><div>Für ein neues Repository muss der Token darauf zugreifen dürfen (bei Neuanlage „All repositories“). Benötigt werden <strong>Contents: Read and write</strong>, <strong>Administration: Read and write</strong> und <strong>Pages: Read and write</strong>. Nach der Anlage kannst du einen neuen Token nur für das Neon-Trinity-Repository erstellen.</div></div><div class="help-step"><div>Kopiere den Token in das Passwortfeld und klicke <strong>GitHub verbinden</strong>. Stelle Benutzername und Repository ein, speichere und wähle <strong>Repository anlegen</strong>. Alternativ kannst du ein öffentliches Repository zuvor direkt bei GitHub anlegen.</div></div><div class="help-step"><div>Öffne ein Album und wähle <strong>Album veröffentlichen</strong>. Der Link zeigt anschließend eine eigene HTML-Seite mit Cover, Titelliste und Player.</div></div></div><p class="notice">Einen Token niemals im Chat senden oder in GitHub-Dateien einfügen.</p>');}
function publishDialog(key){const album=state.albums.find(a=>a.id===key);if(!album)return;if(!team.active)return toast('Melde dich unter Team & Discord an, um Alben zu veröffentlichen.',true);if(!album.trackIds.length)return toast('Füge dem Album zuerst Songs hinzu.');const ids=state.albums.filter(a=>state.published[a.id]).map(a=>a.id);if(!ids.includes(key))ids.push(key);showModal(`<h2>Bereit für die Welt?</h2><p class="subtitle">„${h(album.title)}“ bekommt eine öffentliche Albumseite mit Cover, Titelliste und Player.</p><div class="note"><strong>Albumlink</strong><br><span class="public-link">${h(albumLink(key,state.settings))}</span><br><br>${ids.length} veröffentlichte Alben · Musik und Cover werden aus Supabase geladen.</div><label class="checkbox-line"><input id="publish-consent" type="checkbox"><span>Diese ausgewählten Alben samt Cover und Songs dürfen öffentlich gehört und heruntergeladen werden.</span></label><p class="notice">Eure öffentliche Player-Website muss einmal unter Einstellungen eingerichtet werden. Danach erscheinen Albumfreigaben automatisch.</p><div class="form-actions">${state.published[key]?'<button class="button ghost" id="unpublish-album">Veröffentlichung zurückziehen</button>':''}<button class="button primary" id="publish-now" disabled>↗ Veröffentlichen</button></div><p id="publish-progress" class="progress-text" role="status"></p>`);$('#publish-consent').onchange=e=>$('#publish-now').disabled=!e.target.checked;$('#publish-now').onclick=()=>doPublish(ids);if(state.published[key])$('#unpublish-album').onclick=()=>doPublish(ids.filter(id=>id!==key));}
function syncPublicDialog(){const ids=state.albums.filter(a=>state.published[a.id]).map(a=>a.id);showModal(`<h2>Öffentliche Alben aktualisieren.</h2><p class="subtitle">Die ausgewählten Albumseiten werden mit der gemeinsamen Mediathek abgeglichen.</p><div class="note">${ids.length} öffentliche Alben</div><button class="button primary" id="publish-now">Freigaben aktualisieren</button><p id="publish-progress" role="status"></p>`);$('#publish-now').onclick=()=>doPublish(ids);}
async function doPublish(ids){if(publishing)return;publishing=true;const btn=$('#publish-now');btn.disabled=true;$('#close-modal').disabled=true;const progress=message=>{const el=$('#publish-progress');if(el)el.textContent=message;};try{if(!team.active)throw new Error('Bitte zuerst mit Discord anmelden.');await saveChain;await team.push(structuredClone(state));progress('Albumfreigaben werden in Supabase gespeichert …');const result=await team.api('/api/publish','POST',{albumIds:ids,theme:state.theme});team.accept(result.catalog);await saveState(structuredClone(state));showModal(`<h2>Albumfreigaben gespeichert.</h2><p class="subtitle">${ids.length?'Die freigegebenen Alben sind in Supabase öffentlich abrufbar.':'Die öffentlichen Albumfreigaben wurden entfernt.'}</p><a class="public-link" href="${h(result.url)}" target="_blank" rel="noopener">${h(result.url)}</a><div class="note">Die öffentliche Player-Website muss einmal bereitgestellt werden. Falls der Link noch nicht erreichbar ist: Einstellungen → Optional: GitHub & öffentliche Albumwebsite.</div><p class="notice">Beim Zurückziehen endet die Freigabe. Bereits ausgegebene Dateilinks können noch bis zu fünf Minuten funktionieren; heruntergeladene Kopien bleiben bestehen.</p><div class="form-actions"><button class="button primary" id="publish-done">Fertig</button></div>`);$('#publish-done').onclick=()=>{closeModal();render();};}catch(error){progress('Freigaben konnten nicht vollständig aktualisiert werden: '+error.message);if(btn.isConnected)btn.disabled=false;fail(error);}finally{publishing=false;$('#close-modal').disabled=false;}}
async function createRepoDialog(){showModal(`<h2>Euer eigenes Repository.</h2><p class="subtitle">Es wird ein neues öffentliches Repository unter deinem verbundenen GitHub-Konto angelegt.</p><div class="note"><strong>github.com/${h(state.settings.owner)}/${h(state.settings.repo)}</strong><br>Die Anwendung erstellt das Repository und lädt anschließend ihren Quellcode hoch. Beim ersten Album-Upload wird GitHub Pages für den Ordner docs aktiviert.</div><div class="form-actions"><button class="button primary" id="create-repository-confirm">Öffentliches Repository anlegen</button></div><p id="repo-result" class="notice"></p>`);$('#create-repository-confirm').onclick=async e=>{e.target.disabled=true;try{const result=await ensureRepository(state.settings.owner,state.settings.repo,true);$('#repo-result').textContent='Repository erstellt. App-Quellcode wird hochgeladen …';await seedSourceRepository(state.settings,message=>$('#repo-result').textContent=message);$('#repo-result').innerHTML=`Repository erstellt: <a class="public-link" href="${h(result.html_url)}" target="_blank" rel="noopener">${h(result.html_url)}</a>`;toast('Repository erfolgreich angelegt.');}catch(err){$('#repo-result').textContent=err.message+' Falls das Repository schon angelegt wurde, bleibt es erhalten. Prüfe es bei GitHub, bevor du die Anlage erneut versuchst.';e.target.disabled=false;}};}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function exportBackup(){if(importing)return toast('Bitte den laufenden MP3-Import abwarten.');toast('Vollständiges Backup wird erstellt …');await saveChain;for(const key of new Set([...state.tracks.flatMap(t=>[t.blobId,t.coverBlobId]),...state.albums.map(a=>a.coverBlobId),state.background.blobId].filter(Boolean)))await team.fetchBlob(key);const blobs=await allBlobs();const packed=[];for(const item of blobs)packed.push({key:item.key,type:item.blob.type,data:await base64(item.blob)});const backup={format:'neon-trinity-backup',version:1,createdAt:new Date().toISOString(),state:{...state,privatePlaylists:personalPlaylists(state,team.user?.id)},blobs:packed};download(new Blob([JSON.stringify(backup)],{type:'application/json'}),`Neon-Trinity-${new Date().toISOString().slice(0,10)}.ntbackup`);toast('Backup erstellt. Der Download enthält auch die MP3s.');}
async function importBackup(file){if(!file)return;if(importing)throw new Error('Bitte den laufenden MP3-Import abwarten.');const backup=JSON.parse(await file.text());if(backup.format!=='neon-trinity-backup'||!Array.isArray(backup.blobs))throw new Error('Ungültiges Backup.');const restored=validateState(backup.state);const keys=new Set();const blobs=backup.blobs.map(item=>{if(!/^[a-zA-Z0-9-]{1,80}$/.test(item.key)||keys.has(item.key)||typeof item.data!=='string'||!['audio/mpeg','image/png','image/jpeg','image/webp'].includes(item.type))throw new Error('Das Backup enthält ungültige Dateien.');keys.add(item.key);const bytes=Uint8Array.from(atob(item.data),c=>c.charCodeAt(0));return {key:item.key,blob:new Blob([bytes],{type:item.type})};});for(const t of restored.tracks)if(!keys.has(t.blobId))throw new Error(`Die MP3 von „${t.title}“ fehlt im Backup.`);for(const a of restored.albums)if(a.coverBlobId&&!keys.has(a.coverBlobId))throw new Error('Ein Albumcover fehlt im Backup.');await confirmAction('Studio wiederherstellen?','Die lokale Mediathek, Alben, Playlists und Termine werden durch das Backup ersetzt. Erstelle bei Bedarf vorher ein Backup des jetzigen Studios.','Backup wiederherstellen',async()=>{audio.pause();currentId=null;queue=[];for(const key of urlCache.keys())releaseURL(key);await saveChain;await replaceDatabase(restored,blobs);state=restored;render();renderNowPlaying();toast('Studio vollständig wiederhergestellt.');});}
function quickHelp(){showModal('<h2>Dein Studio in fünf Schritten.</h2><p class="subtitle">Von der ersten MP3 bis zur eigenen Albumseite.</p><div class="help-steps"><div class="help-step"><div><strong>Musik importieren:</strong> MP3-Dateien ins Fenster ziehen oder „MP3 importieren“ klicken. Titel und Stimmen kannst du über ⋯ ändern.</div></div><div class="help-step"><div><strong>Album erstellen:</strong> Unter Alben Titel und Beschreibung vergeben, Cover auswählen, Songs anhaken und die Reihenfolge mit ↑ und ↓ festlegen.</div></div><div class="help-step"><div><strong>Show planen:</strong> Playlist erstellen, die Songs für den Auftritt auswählen und sie beim Termin unter Auftritte als Setlist zuordnen.</div></div><div class="help-step"><div><strong>Album teilen:</strong> Mit Discord anmelden. Im Album „Veröffentlichen“ wählen. Eure öffentliche Player-Website wird einmal in den Einstellungen eingerichtet; neue Albumfreigaben lädt sie danach direkt aus Supabase.</div></div><div class="help-step"><div><strong>Backup machen:</strong> Die vollständige Sicherung unter Einstellungen enthält auch alle MP3s. Verwende sie, um zwischen Browser und Desktop-App zu wechseln.</div></div></div>');}
async function action(name,key,button){switch(name){case'update-check':drawUpdateStatus(await window.neonDesktop.checkForUpdates());break;case'update-download':drawUpdateStatus(await window.neonDesktop.downloadUpdate());break;case'update-install':if(importing||publishing)throw new Error('Bitte zuerst den laufenden Import oder die Veröffentlichung abschließen.');await saveChain.catch(()=>{});await saveState(structuredClone(state));drawUpdateStatus(await window.neonDesktop.installUpdate());break;case'import':$('#audio-files').click();break;case'reset-background':state.background.blobId='';await persist();break;case'mini-player':await window.neonDesktop?.openMini();break;case'team-logout':await listening.leave();await team.logout();render();break;case'team-refresh-identity':await team.resume();render();break;case'publish-web-player':await publishWebPlayer();break;case'team-sync':await persist();await team.pull();render();toast('Gemeinsame Mediathek abgeglichen.');break;case'team-conflict':showTeamConflict();break;case'discord-connect':await configureDiscord();break;case'listen-host':await saveChain;await team.push(structuredClone(state));await listening.host();render();toast('Hörsession gestartet. Der Link kann jetzt geteilt werden.');break;case'listen-stop':await listening.leave();remoteTrack=null;audio.pause();location.hash='team';render();break;case'listen-copy':await navigator.clipboard.writeText(listening.url);toast('Hörlink kopiert.');break;case'resume-listening':await audio.play();break;case'new-album':groupForm('album');break;case'edit-album':groupForm('album',key);break;case'new-playlist':groupForm('playlist');break;case'edit-playlist':groupForm('playlist',key);break;case'new-event':eventForm();break;case'edit-event':eventForm(key);break;case'edit-track':trackForm(key);break;case'add-to-playlist':addToPlaylist(key);break;case'play-track':await playTrack(key,contextQueue(button.dataset.context));break;case'play-album':{const a=state.albums.find(a=>a.id===key);if(a?.trackIds.length)await playTrack(a.trackIds[0],a.trackIds);break;}case'play-playlist':{const p=playlistsForView().find(p=>p.id===key);if(!p?.trackIds.length)return toast('Diese Playlist enthält noch keine Songs.');await playTrack(p.trackIds[0],p.trackIds);break;}case'theme':state.theme=button.dataset.theme;await persist();break;case'publish-album':publishDialog(key);break;case'copy-link':try{await navigator.clipboard.writeText(albumLink(key,state.settings));toast('Albumlink kopiert.');}catch{showModal(`<h2>Albumlink.</h2><p class="public-link">${h(albumLink(key,state.settings))}</p>`);}break;case'create-repo':await createRepoDialog();break;case'sync-public':syncPublicDialog();break;case'disconnect':await disconnect();connected=false;render();toast('GitHub-Verbindung getrennt.');break;case'token-help':tokenHelp();break;case'pages-status':{const target=$('#pages-result');target.textContent='GitHub-Status wird geprüft …';try{const status=await pagesStatus(state.settings);target.textContent=status.message||`Pages: ${status.status} · ${status.url||''}${status.error?` · ${status.error}`:''}`;}catch(e){target.textContent=e.message;}break;}case'export-backup':await exportBackup();break;case'import-backup':$('#backup-file').click();break;case'quick-help':quickHelp();break;case'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;}else showModal('<h2>Studio installieren.</h2><p class="subtitle">Öffne diese Seite in Microsoft Edge oder Google Chrome. Klicke rechts in der Adressleiste auf das Installationssymbol. Alternativ: Browsermenü → Apps → Diese Seite als App installieren.</p><div class="note">Nach dem Installieren öffnet sich Neon Trinity in einem eigenen Fenster und lässt sich an die Taskleiste heften.</div>');break;}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(button){action(button.dataset.action,button.dataset.id,button).catch(fail);}const view=e.target.closest('[data-view]');if(view)location.hash=view.dataset.view;});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('.upload-zone'))$('#audio-files').click();if(e.key==='/'&&!e.target.matches('input,textarea,select')){e.preventDefault();$('#global-search').focus();}if(e.code==='Space'&&!e.target.matches('input,textarea,select,button,a')&&!$('#modal').open){e.preventDefault();$('#play-pause').click();}});
$('#audio-files').onchange=e=>importFiles([...e.target.files]).catch(fail);$('#backup-file').onchange=e=>{importBackup(e.target.files[0]).catch(fail);e.target.value='';};
$('#import-top').onclick=()=>$('#audio-files').click();$('#sidebar-new').onclick=()=>groupForm('playlist');$('#close-modal').onclick=()=>{if(!publishing)closeModal();};$('#modal').addEventListener('cancel',e=>{if(publishing)e.preventDefault();});
$('#global-search').oninput=e=>{search=e.target.value;if(!['library','albums','playlists','events'].includes(currentView)){preserveSearch=true;location.hash='library';}else render();};
$('#theme-cycle').onclick=async()=>{const keys=Object.keys(THEMES);state.theme=keys[(keys.indexOf(state.theme)+1)%keys.length];await persist();};
window.addEventListener('hashchange',()=>{if(!preserveSearch){search='';$('#global-search').value='';}preserveSearch=false;render();window.scrollTo({top:0});});
$('#play-pause').onclick=()=>{if(currentId){if(audio.paused)audio.play().catch(fail);else audio.pause();}else if(state.tracks.length)playTrack(state.tracks[0].id,state.tracks.map(t=>t.id)).catch(fail);else toast('Importiere zuerst einen Song.');};
$('#previous').onclick=()=>{if(audio.currentTime>3)audio.currentTime=0;else nextTrack(-1);};$('#next').onclick=()=>nextTrack(1);$('#shuffle').onclick=e=>{shuffle=!shuffle;e.currentTarget.setAttribute('aria-pressed',String(shuffle));};$('#repeat').onclick=e=>{repeat=!repeat;e.currentTarget.setAttribute('aria-pressed',String(repeat));};
$('#seek').oninput=e=>{if(Number.isFinite(audio.duration))audio.currentTime=Number(e.target.value)/100*audio.duration;};$('#volume').oninput=e=>audio.volume=Number(e.target.value);
audio.addEventListener('play',()=>{$('#play-pause').textContent='Ⅱ';$('#play-pause').setAttribute('aria-label','Pause');});audio.addEventListener('pause',()=>{$('#play-pause').textContent='▶';$('#play-pause').setAttribute('aria-label','Abspielen');});audio.addEventListener('timeupdate',()=>{$('#elapsed').textContent=time(audio.currentTime);$('#seek').value=Number.isFinite(audio.duration)?audio.currentTime/audio.duration*100:0;});audio.addEventListener('ended',()=>nextTrack(1,true));audio.addEventListener('error',()=>{if(currentId)toast('Diese MP3 kann nicht abgespielt werden.',true);});
$('#queue-button').onclick=()=>{const tracks=queue.map(k=>state.tracks.find(t=>t.id===k)).filter(Boolean);showModal(`<h2>In der Warteschlange.</h2><p class="subtitle">${tracks.length} Songs · ${time(duration(queue,state.tracks))}</p><div class="selection-list">${tracks.length?tracks.map(t=>`<button class="track-choice" data-action="play-track" data-context="queue" data-id="${h(t.id)}"><span>${h(t.title)}</span><small>${time(t.duration)}</small></button>`).join(''):'<p class="notice">Starte ein Album oder eine Playlist.</p>'}</div>`);};
let dragDepth=0;document.addEventListener('dragenter',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();dragDepth++;$('#drop-overlay').hidden=false;}});document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault();});document.addEventListener('dragleave',()=>{dragDepth=Math.max(0,dragDepth-1);if(!dragDepth)$('#drop-overlay').hidden=true;});document.addEventListener('drop',e=>{e.preventDefault();dragDepth=0;$('#drop-overlay').hidden=true;if(e.dataTransfer.files.length)importFiles([...e.dataTransfer.files]).catch(fail);});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('error',e=>{if(e.message)toast(e.message,true);});window.addEventListener('unhandledrejection',e=>{e.preventDefault();fail(e.reason);});
try{state=validateState(await loadState()||newState());if(window.neonDesktop)connected=await window.neonDesktop.hasToken();render();if(navigator.storage?.estimate){const estimate=await navigator.storage.estimate();$('#storage-status').textContent=`${((estimate.usage||0)/1024/1024).toFixed(1)} MiB lokal · v${STUDIO_VERSION}`;}}catch(e){fail(e);$('#main').innerHTML=empty('Die Mediathek konnte nicht geöffnet werden.','Bitte erlaube lokalen Speicher und lade das Studio erneut.');}
if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});

async function applyBackground(){const layer=$('#personal-background');if(!layer)return;const key=state.background.blobId;if(!key){layer.style.backgroundImage='none';return;}const url=await objectURL(key);if(state.background.blobId!==key)return;layer.style.backgroundImage=url?`url("${url}")`:'none';layer.style.opacity=String(1-state.background.dim/100);layer.style.filter=`blur(${state.background.blur}px)`;}
function bindBackgroundSettings(){const input=$('#background-file');if(!input)return;input.onchange=async e=>{const file=e.target.files[0];if(!file)return;try{validateImage(file);const key=id();await putBlob(key,new Blob([file],{type:file.type}));state.background.blobId=key;await persist();toast('Eigener Hintergrund gespeichert.');}catch(err){fail(err);}};for(const [selector,key,label,suffix] of [['#background-dim','dim','#dim-label','%'],['#background-blur','blur','#blur-label','px']]){$(selector).oninput=e=>{state.background[key]=Number(e.target.value);$(label).textContent=e.target.value+suffix;applyBackground();};$(selector).onchange=()=>persist(false).catch(fail);}}
function bindTeamForms(){const form=$('#team-server-form');if(form)form.onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{await team.configure();const login=await team.login();if(login){showModal('<h2>Mit Discord anmelden.</h2><p class="subtitle">Dein Browser wurde geöffnet. Melde dich dort mit deinem Discord-Konto an und kehre anschließend zum Studio zurück.</p><p id="pair-status" class="progress-text">Warte auf Discord …</p>');let attempts=0,busy=false;const timer=setInterval(async()=>{if(!$('#modal').open||++attempts>150){clearInterval(timer);await window.neonDesktop?.cloudCancelLogin?.();return;}if(busy)return;busy=true;try{const result=await team.pollLogin();if(result.status==='ready'){clearInterval(timer);closeModal();await activateDiscordFromTeam();render();toast(team.user?'Willkommen, '+team.user.alias+'. Eure Mediathek wird gemeinsam genutzt.':'Discord-Anmeldung erfolgreich. Dieses Konto muss noch freigeschaltet werden.');}}catch(error){clearInterval(timer);closeModal();fail(error);render();}finally{busy=false;}},1800);timer.unref?.();}}catch(error){fail(error);if(button.isConnected)button.disabled=false;}};const publicForm=$('#public-base-form');if(publicForm)publicForm.onsubmit=async event=>{event.preventDefault();try{const base=safeBaseUrl(new FormData(event.target).get('publicBase'));if(!base)throw new Error('Bitte eine öffentliche HTTPS-Website-Adresse eingeben.');team.info=await team.backend.setConfig({public_base:base});state.settings.publicBase=base;await persist();toast('Website-Adresse für das Team gespeichert.');}catch(error){fail(error);}};const join=$('#join-listen-form');if(join)join.onsubmit=event=>{event.preventDefault();joinListeningURL(new FormData(event.target).get('link')).catch(fail);};}
async function joinListeningURL(input){const url=new URL(input);if(url.protocol!=='https:'||url.username||url.password)throw new Error('Ungültiger Hörlink.');const room=url.searchParams.get('room')||url.hash.match(/^#listen\/([a-f0-9]{64})$/)?.[1];if(!/^[a-f0-9]{64}$/.test(room||''))throw new Error('Dieser Link enthält keine Hörsession.');location.hash='listen/'+room;await listening.join(room);render();}
async function activateDiscordFromTeam(){const clientId=team.info?.discordClientId;if(window.neonDesktop?.configureDiscord&&clientId){state.settings.discordClientId=clientId;await window.neonDesktop.configureDiscord(clientId);}}
async function configureDiscord(){const clientId=$('#discord-client-id')?.value.trim()||state.settings.discordClientId;if(!/^\d{16,22}$/.test(clientId||''))throw new Error('Bitte eine gültige Discord Application ID eingeben.');await window.neonDesktop.configureDiscord(clientId);state.settings.discordClientId=clientId;if(team.user?.alias==='Dex'){team.info=await team.backend.setConfig({discord_client_id:clientId});}await persist(false);toast('Discord-Verbindung wird hergestellt.');}
function showTeamConflict(){const conflict=team.conflict;if(!conflict)return;showModal(`<h2>Gleichzeitig bearbeitet.</h2><p class="subtitle">Ein Bandmitglied hat denselben Eintrag geändert. Deine lokale Fassung bleibt erhalten, bis du dich entscheidest.</p><div class="note">${conflict.operations.filter(o=>o.kind!=='assets').slice(0,8).map(o=>{const remote=conflict.remote?.[o.kind]?.find(r=>r.id===o.id);return `<strong>${h(o.value?.title||remote?.title||o.kind)}</strong><br>Deine Fassung: ${h(JSON.stringify(o.value).slice(0,450))}<br>Team-Fassung: ${h(JSON.stringify(remote||null).slice(0,450))}`;}).join('<hr>')}</div><div class="form-actions"><button class="button ghost" id="take-team">Team-Fassung übernehmen</button><button class="button primary" id="keep-local">Meine Änderungen übernehmen</button></div>`);$('#take-team').onclick=()=>team.resolve(false).then(()=>{closeModal();render();}).catch(fail);$('#keep-local').onclick=()=>team.resolve(true).then(()=>{closeModal();render();}).catch(fail);}
async function syncRemotePlayer(room,position){const track=room.track;if(!track)return;const changed=currentId!==track.id||!remoteTrack;if(changed){remoteTrack={...track,voices:'Hörsession mit '+room.host};currentId=track.id;queue=[];audio.src=room.mediaUrl;renderNowPlaying();}if(Math.abs((audio.currentTime||0)-position)>1.2||changed){try{audio.currentTime=position;}catch{}}if(room.playing&&audio.paused)await audio.play().catch(()=>toast('Klicke unten auf ▶, um mitzuhören.'));else if(!room.playing&&!audio.paused)audio.pause();updateDesktopPlayer();}
function updateDesktopPlayer(){if(!window.neonDesktop?.updatePlayer)return;const track=state.tracks.find(t=>t.id===currentId)||remoteTrack;window.neonDesktop.updatePlayer({title:track?.title||'',artist:track?.artist||'Neon Trinity',position:audio.currentTime||0,duration:track?.duration||0,paused:audio.paused,roomUrl:listening.url|| (listening.followRoom?`${team.info.publicBase}/album.html?room=${listening.followRoom.id}`:'')}).catch(()=>{});}
if(window.neonDesktop?.openMini){$('#mini-player').hidden=false;$('#mini-player').onclick=()=>window.neonDesktop.openMini().catch(fail);window.neonDesktop.onPlayerCommand(command=>{if(command.command==='toggle')$('#play-pause').click();else if(command.command==='next')nextTrack(1);else if(command.command==='previous')nextTrack(-1);else if(command.command==='seek'&&Number.isFinite(audio.duration))audio.currentTime=Math.max(0,Math.min(1,command.value))*audio.duration;});window.neonDesktop.onDiscordStatus(message=>{discordStatus=message;const el=$('#discord-status');if(el)el.textContent=message;});}
for(const event of ['play','pause','seeked','loadedmetadata'])audio.addEventListener(event,()=>{updateDesktopPlayer();if(listening.hostRoom)listening.updateHost().catch(fail);});let desktopTimer=setInterval(updateDesktopPlayer,1000);desktopTimer.unref?.();
window.addEventListener('hashchange',()=>{const room=location.hash.match(/^#listen\/([a-f0-9]{64})$/)?.[1];if(room&&listening.followRoom?.id!==room){if(!team.base&&!window.neonDesktop)team.base=location.origin;listening.join(room).then(render).catch(fail);}});
if(window.neonDesktop?.onUpdateStatus){window.neonDesktop.onUpdateStatus(drawUpdateStatus);window.neonDesktop.updateStatus().then(drawUpdateStatus).catch(fail);}
team.detect().then(async()=>{await activateDiscordFromTeam();if(window.neonDesktop&&!location.hash&&!team.user&&!state.tracks.length)location.hash='team';render();const room=location.hash.match(/^#listen\/([a-f0-9]{64})$/)?.[1];if(room){if(!team.base&&!window.neonDesktop)team.base=location.origin;await listening.join(room);render();}}).catch(()=>{});

async function publishWebPlayer(){if(!connected)throw new Error('Bitte zuerst die optionale GitHub-Verbindung einrichten.');if(!team.active){location.hash='team';render();throw new Error('Melde dich zuerst unter Team & Discord an. Danach erkennt das Studio dein freigeschaltetes Dex-Konto.');}if(team.user.alias!=='Dex')throw new Error('Du bist als '+team.user.alias+' angemeldet. Die gemeinsame Website-Einstellung verwaltet Dex.');showModal('<h2>Öffentliche Player-Website.</h2><p class="subtitle">Es werden nur die Player-Dateien zu GitHub hochgeladen. Musik und Cover bleiben in Supabase.</p><p id="web-progress" role="status">Website wird vorbereitet …</p>');const result=await publishFiles(state.settings,await collectCloudSite(),message=>{const el=$('#web-progress');if(el)el.textContent=message;});const base=safeBaseUrl(state.settings.baseUrl||result.url);team.info=await team.backend.setConfig({public_base:base});state.settings.publicBase=base;await persist(false);showModal(`<h2>Player-Website hochgeladen.</h2><p class="subtitle">GitHub Pages baut die Website. Nach dem erfolgreichen Build funktionieren Album- und Hörlinks für Gäste.</p><a class="public-link" href="${h(base)}/album.html" target="_blank" rel="noopener">${h(base)}/album.html</a><p class="notice">Den tatsächlichen Build-Status findest du in den Einstellungen.</p>`);}
